const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(157.706220, -34.344553);
  const areaOfInterest = point.buffer(100000); // 100km radius

  const startDate1 = '2019-11-01';
  const endDate1 = '2020-02-29'; // Period of interest (Black Summer)
  const startDate2 = '2018-11-01';
  const endDate2 = '2019-02-28'; // Comparison period (previous year)

  const band = 'BCEXTTAU'; // Black Carbon Extinction AOD

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MERRA/M2T1NXAER').select(band);

  const col1 = collection.filterDate(startDate1, endDate1);
  const col2 = collection.filterDate(startDate2, endDate2);

  const col1Size = col1.size().getInfo();
  const col2Size = col2.size().getInfo();

  if (col1Size === 0 || col2Size === 0) {
    console.log(`Image count 2019-2020: ${col1Size}`);
    console.log(`Image count 2018-2019: ${col2Size}`);
    console.log('C1: Empty Collection');
    return;
  }
  console.log(`Image count 2019-2020: ${col1Size}`);
  console.log(`Image count 2018-2019: ${col2Size}`);

  // 3. Processing
  const meanImage1 = col1.mean();
  const meanImage2 = col2.mean();

  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = meanImage1.reduceRegion({
    reducer: reducers,
    geometry: areaOfInterest,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = meanImage2.reduceRegion({
    reducer: reducers,
    geometry: areaOfInterest,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  // 4. Calculation & Validation
  const mean1 = stats1[`${band}_mean`];
  const count1 = stats1[`${band}_count`];
  const mean2 = stats2[`${band}_mean`];
  const count2 = stats2[`${band}_count`];

  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels 2019-2020: ${count1}`);
    console.log(`Valid pixels 2018-2019: ${count2}`);
    console.log('C2: No Valid Pixels');
    return;
  }

  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log(`Mean AOD 2019-2020: ${mean1}`);
    console.log(`Mean AOD 2018-2019: ${mean2}`);
    console.log('C3: Calculation Failure');
    return;
  }

  console.log(`Mean Black Carbon AOD (2019-2020): ${mean1.toFixed(5)}`);
  console.log(`Mean Black Carbon AOD (2018-2019): ${mean2.toFixed(5)}`);

  // 5. Final Answer
  if (mean1 > mean2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
